import { AbsoluteFill, Audio, Img, Sequence, interpolate, spring, staticFile, useCurrentFrame, useVideoConfig, Easing } from 'remotion'
import timings from '../public/voice-timings.json'

/*
 * 30 s, 1920x1080. Every image is a real capture of the LASTLIGHT web app (Mission mode, Crash Test).
 * Cuts follow the recorded voice (assets/audio/voice.mp3, Whisper timings). Score is generated by
 * video/scripts/make_score.py. No stock footage, no logos.
 */

const S = (sec: number) => Math.round(sec * 30)
const AMBER = '#ffb547'
const FG = '#ecebe6'
const FG2 = '#a3a3a0'
const FAIL = '#ff5a4e'
const sans = "'Geist Variable', system-ui, sans-serif"
const mono = "'Geist Mono Variable', ui-monospace, monospace"
const ease = Easing.bezier(0.16, 1, 0.3, 1)

/** Slow push-in / drift on a still, with fade in and out. */
function Still({ src, dur, from = 1.0, to = 1.08, x = 0, y = 0, fadeIn = 12, fadeOut = 10 }: { src: string; dur: number; from?: number; to?: number; x?: number; y?: number; fadeIn?: number; fadeOut?: number }) {
  const f = useCurrentFrame()
  const p = interpolate(f, [0, dur], [0, 1], { extrapolateRight: 'clamp', easing: Easing.inOut(Easing.quad) })
  const op = Math.min(interpolate(f, [0, fadeIn], [0, 1], { extrapolateRight: 'clamp' }), interpolate(f, [dur - fadeOut, dur], [1, 0], { extrapolateLeft: 'clamp' }))
  return (
    <AbsoluteFill style={{ opacity: op, overflow: 'hidden' }}>
      <Img src={staticFile(src)} style={{ width: '100%', height: '100%', objectFit: 'cover', transform: `translate(${x * p}px, ${y * p}px) scale(${from + (to - from) * p})` }} />
    </AbsoluteFill>
  )
}

/** Plays the captured ground frames as a time-lapse (reversed: Sun visible, then hidden by the ridge). */
function GroundLapse({ dur }: { dur: number }) {
  const f = useCurrentFrame()
  const n = 71
  const i = Math.min(n - 1, Math.floor(interpolate(f, [0, dur], [0, n - 1], { extrapolateRight: 'clamp' })))
  const idx = n - 1 - i
  const darken = interpolate(f, [dur * 0.62, dur], [0, 0.55], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' })
  const op = Math.min(interpolate(f, [0, 8], [0, 1], { extrapolateRight: 'clamp' }), interpolate(f, [dur - 8, dur], [1, 0], { extrapolateLeft: 'clamp' }))
  return (
    <AbsoluteFill style={{ opacity: op }}>
      <Img src={staticFile(`shots/ground_${String(idx).padStart(3, '0')}.jpg`)} style={{ width: '100%', height: '100%', objectFit: 'cover', transform: `scale(${1.04 + 0.03 * (f / dur)})` }} />
      <AbsoluteFill style={{ background: '#000', opacity: darken }} />
    </AbsoluteFill>
  )
}

function Reveal({ children, delay = 0, style }: { children: React.ReactNode; delay?: number; style?: React.CSSProperties }) {
  const f = useCurrentFrame()
  const { fps } = useVideoConfig()
  const s = spring({ frame: f - delay, fps, config: { damping: 200, mass: 0.6 } })
  return <div style={{ opacity: s, transform: `translateY(${(1 - s) * 18}px)`, ...style }}>{children}</div>
}

function Kicker({ children, color = FG2 }: { children: React.ReactNode; color?: string }) {
  return <div style={{ fontFamily: mono, fontSize: 26, color, letterSpacing: '0.02em' }}>{children}</div>
}

/** Burned-in subtitles from the Whisper segments, matched to the script wording. */
const LINES: { start: number; end: number; text: string }[] = timings.segments.map((s: { start: number; end: number; text: string }) => ({
  start: s.start,
  end: s.end,
  text: s.text.replace('Last Light', 'LASTLIGHT').replace('South Pole', 'south pole').replace('the sun', 'the Sun'),
}))

function Subtitles() {
  const f = useCurrentFrame()
  const t = f / 30
  const line = LINES.find((l) => t >= l.start && t < l.end + 0.05)
  if (!line) return null
  const local = (t - line.start) * 30
  const op = interpolate(local, [0, 5], [0, 1], { extrapolateRight: 'clamp' })
  return (
    <AbsoluteFill style={{ justifyContent: 'flex-end', alignItems: 'center', paddingBottom: 70 }}>
      <div style={{ opacity: op, fontFamily: sans, fontWeight: 500, fontSize: 42, color: FG, background: 'rgba(7,8,11,0.62)', padding: '10px 22px', letterSpacing: '-0.01em', maxWidth: 1500, textAlign: 'center' }}>
        {line.text}
      </div>
    </AbsoluteFill>
  )
}

function Vignette() {
  return <AbsoluteFill style={{ background: 'radial-gradient(120% 90% at 50% 45%, transparent 55%, rgba(0,0,0,0.55) 100%)', pointerEvents: 'none' }} />
}

export function LastLight() {
  return (
    <AbsoluteFill style={{ background: '#05060a', fontFamily: sans }}>
      <Audio src={staticFile('voice.mp3')} />
      <Audio src={staticFile('score.wav')} volume={0.55} />

      {/* 1. 0 - 7.5 s: Athena. Black, date, then the landing site on real terrain. */}
      <Sequence from={0} durationInFrames={S(7.5)}>
        <Sequence from={S(2.0)} durationInFrames={S(5.5)}>
          <Still src="shots/athena.png" dur={S(5.5)} from={1.12} to={1.0} y={-20} fadeIn={20} fadeOut={8} />
        </Sequence>
        <AbsoluteFill style={{ padding: '120px 140px', justifyContent: 'flex-start' }}>
          <Reveal delay={6}>
            <Kicker>6 March 2025</Kicker>
          </Reveal>
          <Reveal delay={S(2.2)}>
            <div style={{ fontSize: 84, fontWeight: 600, color: FG, letterSpacing: '-0.035em', marginTop: 18, lineHeight: 1 }}>Athena lands at the pole.</div>
          </Reveal>
          <Reveal delay={S(5.0)}>
            <div style={{ fontFamily: mono, fontSize: 64, color: FAIL, marginTop: 26 }}>+13 h. Silent.</div>
          </Reveal>
        </AbsoluteFill>
      </Sequence>

      {/* 2. 7.5 - 11.64 s: the Moon, title card. */}
      <Sequence from={S(7.5)} durationInFrames={S(11.64 - 7.5)}>
        <Still src="shots/moon.png" dur={S(4.14)} from={1.0} to={1.07} x={-40} fadeIn={14} fadeOut={8} />
        <AbsoluteFill style={{ padding: '0 140px', justifyContent: 'center' }}>
          <Reveal delay={8}>
            <div style={{ fontSize: 132, fontWeight: 600, color: FG, letterSpacing: '-0.045em', lineHeight: 0.95 }}>LASTLIGHT</div>
          </Reveal>
          <Reveal delay={20}>
            <div style={{ width: 120, height: 3, background: AMBER, margin: '30px 0' }} />
          </Reveal>
          <Reveal delay={26}>
            <div style={{ fontSize: 34, color: FG2, lineHeight: 1.4 }}>
              Lunar Landing Site Navigator
              <br />
              Casablanca, We Have A Solution
            </div>
          </Reveal>
        </AbsoluteFill>
      </Sequence>

      {/* 3. 9.84 - 14.28 s: on the ground, the Sun slides behind a ridge (time-lapse of the app). */}
      <Sequence from={S(11.0)} durationInFrames={S(14.28 - 11.0)}>
        <GroundLapse dur={S(3.28)} />
        <AbsoluteFill style={{ padding: '110px 140px' }}>
          <Reveal delay={6}>
            <Kicker color={AMBER}>Haworth, ground view</Kicker>
          </Reveal>
        </AbsoluteFill>
      </Sequence>

      {/* 4. 14.28 - 19.62 s: simulated landings, then the real terrain under the words "NASA's real terrain". */}
      <Sequence from={S(14.28)} durationInFrames={S(16.4 - 14.28)}>
        <Still src="shots/crash.png" dur={S(2.12)} from={1.12} to={1.02} fadeIn={8} fadeOut={8} />
        <AbsoluteFill style={{ padding: '110px 140px' }}>
          <Reveal delay={6}>
            <Kicker>Each column is one simulated landing</Kicker>
          </Reveal>
        </AbsoluteFill>
      </Sequence>
      <Sequence from={S(16.24)} durationInFrames={S(19.62 - 16.24)}>
        <Still src="shots/pole.png" dur={S(3.38)} from={1.0} to={1.1} y={20} fadeIn={8} fadeOut={8} />
        <AbsoluteFill style={{ padding: '110px 140px' }}>
          <Reveal delay={6}>
            <Kicker>Built on NASA LOLA terrain</Kicker>
          </Reveal>
        </AbsoluteFill>
      </Sequence>

      {/* 5. 19.62 - 23.46 s: where, when, survive. */}
      <Sequence from={S(19.62)} durationInFrames={S(23.46 - 19.62)}>
        <Still src="shots/pole.png" dur={S(3.84)} from={1.14} to={1.02} fadeIn={10} fadeOut={10} />
        <AbsoluteFill style={{ background: 'rgba(5,6,10,0.45)' }} />
        <AbsoluteFill style={{ padding: '0 140px', justifyContent: 'center' }}>
          {['Where.', 'When.', 'Will it survive?'].map((w, i) => (
            <Reveal key={w} delay={8 + i * 18}>
              <div style={{ fontSize: 112, fontWeight: 600, color: i === 2 ? AMBER : FG, letterSpacing: '-0.04em', lineHeight: 1.04 }}>{w}</div>
            </Reveal>
          ))}
        </AbsoluteFill>
      </Sequence>

      {/* 6. 23.46 - 30 s: outro. */}
      <Sequence from={S(23.46)} durationInFrames={S(30 - 23.46)}>
        <Still src="shots/moon.png" dur={S(6.54)} from={1.06} to={1.0} x={30} fadeIn={14} fadeOut={24} />
        <AbsoluteFill style={{ padding: '0 140px', justifyContent: 'center' }}>
          <Reveal delay={6}>
            <div style={{ fontSize: 96, fontWeight: 600, color: FG, letterSpacing: '-0.04em' }}>LASTLIGHT</div>
          </Reveal>
          <Reveal delay={18}>
            <div style={{ fontSize: 36, color: FG2, marginTop: 18 }}>Open source, for every mission to the pole.</div>
          </Reveal>
          <Reveal delay={30}>
            <div style={{ fontFamily: mono, fontSize: 28, color: AMBER, marginTop: 28 }}>github.com/ShizKN/lastlight</div>
          </Reveal>
        </AbsoluteFill>
      </Sequence>

      <Vignette />
      <Subtitles />

      {/* Disclosure required by the rules: visible the whole time, small. */}
      <AbsoluteFill style={{ justifyContent: 'flex-start', alignItems: 'flex-end', padding: '36px 44px', pointerEvents: 'none' }}>
        <div style={{ fontFamily: mono, fontSize: 18, color: 'rgba(236,235,230,0.55)' }}>AI-generated voice</div>
      </AbsoluteFill>
    </AbsoluteFill>
  )
}
